def rpn_add_multiply(tokens):
    stack = []
    for token in tokens:
        if token in ('+', '*'):
            right, left = stack.pop(), stack.pop()
            stack.append(left + right if token == '+' else left * right)
        else:
            stack.append(int(token))
    return stack[0]

