def transfer_each(initial, transfers):
    balances = dict(initial)
    accepted = []
    for src, dst, amount in transfers:
        ok = balances[src] >= amount
        accepted.append(ok)
        if ok:
            balances[src] -= amount
            balances[dst] += amount
    return {'balances': balances, 'accepted': accepted}

tests.source:
