def shortest_hops(edges, source, target):
    queue = [[source]]
    while queue:
        path = queue.pop(0)
        if path[-1] == target:
            return path
        for node in sorted({right for left, right in edges if left == path[-1]}):
            if node not in path:
                queue.append(path + [node])
    return None

